1	import {
2	  ApplicationRef,
3	  EnvironmentInjector,
4	  Injectable,
5	  createComponent,
6	  inject,
7	} from '@angular/core';
8	import { ConfirmDialogComponent, ConfirmOptions } from './confirm-dialog.component';
9	
10	/** Awaitable confirmation usable from guards and components. */
11	@Injectable({ providedIn: 'root' })
12	export class ConfirmDialogService {
13	  private readonly appRef = inject(ApplicationRef);
14	  private readonly injector = inject(EnvironmentInjector);
15	
16	  confirm(options: ConfirmOptions): Promise<boolean> {
17	    return new Promise<boolean>((resolve) => {
18	      const previouslyFocused =
19	        document.activeElement instanceof HTMLElement ? document.activeElement : null;
20	      const ref = createComponent(ConfirmDialogComponent, { environmentInjector: this.injector });
21	      ref.setInput('options', options);
22	      let done = false;
23	      const subscription = ref.instance.closed.subscribe((result) => {
24	        if (done) return;
25	        done = true;
26	        subscription.unsubscribe();
27	        this.appRef.detachView(ref.hostView);
28	        ref.destroy();
29	        previouslyFocused?.focus();
30	        resolve(result);
31	      });
32	      this.appRef.attachView(ref.hostView);
33	      document.body.appendChild(ref.location.nativeElement);
34	      ref.changeDetectorRef.detectChanges();
35	    });
36	  }
37	}
